-- BPC-DEV-RECONCILIATION REVERSAL for batch S8 (owner-approved use only)
SET LOCAL lock_timeout = '3s';
SELECT pg_advisory_xact_lock(hashtext('bpc-dev-reconciliation'));
DO $bpc$
DECLARE before_n bigint;
BEGIN
  SELECT count(*) INTO before_n FROM supabase_migrations.schema_migrations;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = ANY(ARRAY['20251129190039','20251129190013','20251207185927','20251207184549','20251003200318','20251229223230','20251208143543','20260323201502','20260324012349','20260324051459','20260324142355','20260324150838','20260324154955','20260324180043','20251008153325','20251207172335','20251208130213','20251208130034','20251208125821','20251213223934','20251214230102','20251209124058','20251003111105','20251003122900','20251008155607','20251202171808','20251203125006','20251205115557','20251207163822','20251230184205','20251230184228','20251207175214','20251207161003','20251231161729','20260305010355','20260311105210','20260311111714','20260317175547','20260322203356','20260323175233','20251008190000']) AND statements[1] LIKE '-- BPC-DEV-RECONCILIATION%batch=S8;%') <> 41 THEN RAISE EXCEPTION 'batch rows not exactly as expected'; END IF;
  DELETE FROM supabase_migrations.schema_migrations WHERE version = ANY(ARRAY['20251129190039','20251129190013','20251207185927','20251207184549','20251003200318','20251229223230','20251208143543','20260323201502','20260324012349','20260324051459','20260324142355','20260324150838','20260324154955','20260324180043','20251008153325','20251207172335','20251208130213','20251208130034','20251208125821','20251213223934','20251214230102','20251209124058','20251003111105','20251003122900','20251008155607','20251202171808','20251203125006','20251205115557','20251207163822','20251230184205','20251230184228','20251207175214','20251207161003','20251231161729','20260305010355','20260311105210','20260311111714','20260317175547','20260322203356','20260323175233','20251008190000']) AND statements[1] LIKE '-- BPC-DEV-RECONCILIATION%batch=S8;%';
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations) <> before_n - 41 THEN RAISE EXCEPTION 'ledger count after reversal is not the pre-reversal count minus the batch'; END IF;
END $bpc$;
